package org.myforeverpet.paradise;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{
 private final PetRuntime pet=PetRuntime.get();private final PetArt art=new PetArt();private final Handler h=new Handler(Looper.getMainLooper());
 private int zoom=2,hits=0,remaining=0,displayedStage=-1;private boolean playing=false,active=false;private long gameEnd;private float targetX=.5f,targetY=.5f;
 private TextView status,caption;private LinearLayout actions;private View scene;
 private final Runnable refresh=new Runnable(){public void run(){if(!active)return;if(playing&&SystemClock.elapsedRealtime()>=gameEnd)finishGame();update();h.postDelayed(this,100);}};
 private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);pet.init(this);getWindow().setStatusBarColor(0xff17243c);getWindow().setNavigationBarColor(0xff17243c);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(0xff171b39);
 TextView title=new TextView(this);title.setText("MY FOREVER PET");title.setTextSize(24);title.setTypeface(Typeface.create("sans-serif-black",0));title.setTextColor(0xfff7edff);title.setGravity(17);root.addView(title);
 status=new TextView(this);status.setTextColor(0xff253851);status.setGravity(17);root.addView(status);
 scene=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){if(playing){c.drawColor(0xffd9f3ef);p.setColor(0xffeab75b);Path star=new Path();for(int i=0;i<10;i++){double angle=-Math.PI/2+i*Math.PI/5;float r=dp(i%2==0?28:13);float x=targetX*getWidth()+(float)Math.cos(angle)*r,y=targetY*getHeight()+(float)Math.sin(angle)*r;if(i==0)star.moveTo(x,y);else star.lineTo(x,y);}star.close();c.drawPath(star,p);p.setColor(0xff34475e);p.setTextSize(dp(19));p.setTextAlign(Paint.Align.CENTER);c.drawText("Tap the star  •  "+hits+" hits",getWidth()/2f,dp(30),p);}else art.draw(c,pet.snapshot(),zoom,false,SystemClock.elapsedRealtime());}
 @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){if(playing){float dx=e.getX()-targetX*getWidth(),dy=e.getY()-targetY*getHeight();if(dx*dx+dy*dy<dp(32)*dp(32)){hits++;targetX=.15f+(float)Math.random()*.7f;targetY=.2f+(float)Math.random()*.65f;invalidate();}}else if(pet.snapshot().stage==0){pet.action(0,0);rebuild();}else if(zoom==3){PetState p=pet.snapshot();if(p.sick)pet.action(4,0);else pet.action(5,0);update();}return true;}return true;}};
 root.addView(scene,new LinearLayout.LayoutParams(-1,0,1));
 caption=new TextView(this);caption.setGravity(17);caption.setTextColor(0xffdfd0ff);root.addView(caption);
 LinearLayout zooms=new LinearLayout(this);String[] names={"Space","Field","Pet","Cell"};for(int i=0;i<4;i++){final int z=i;button(zooms,names[i],()->{if(playing)finishGame();zoom=z;rebuild();});}root.addView(zooms);
 actions=new LinearLayout(this);actions.setOrientation(1);root.addView(actions);
 LinearLayout footer=new LinearLayout(this);button(footer,"Lab",()->lab());button(footer,"Live wallpaper",()->{Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,PetWallpaper.class));try{startActivity(i);}catch(ActivityNotFoundException e){Toast.makeText(this,"Wallpaper picker unavailable",0).show();}});root.addView(footer);setContentView(root);rebuild();}
 private void button(LinearLayout row,String label,Runnable run){Button b=new Button(this);b.setAllCaps(false);b.setText(label);b.setTextSize(13);b.setTypeface(Typeface.create("sans-serif-medium",0));b.setTextColor(0xff241c46);b.setMinWidth(0);b.setMinHeight(0);b.setPadding(dp(4),0,dp(4),0);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xfff4e9ff,0xffbfb1f6});bg.setCornerRadius(dp(15));bg.setStroke(dp(2),0xff7966b8);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x55816bdb),bg,null));b.setElevation(dp(2));b.setOnClickListener(v->run.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(46),1);lp.setMargins(dp(3),dp(4),dp(3),dp(4));row.addView(b,lp);}
 private void lab(){new AlertDialog.Builder(this).setTitle("FOREVER LAB").setItems(new String[]{"Shop","Inventory","Creature collection","Space travel"},(d,i)->{if(i==0)shop(false);else if(i==1)shop(true);else if(i==2){PetState p=pet.snapshot();StringBuilder b=new StringBuilder();for(int n=0;n<PetState.SPECIES.length;n++)b.append((p.collection&(1<<n))!=0?PetState.SPECIES[n]:"????").append("\n");new AlertDialog.Builder(this).setTitle("Creature collection").setMessage(b.toString()).setPositiveButton("Close",null).show();}else{PetState p=pet.snapshot();new AlertDialog.Builder(this).setTitle("Space travel").setMessage("Biofuel: "+p.fuel+"/4").setPositiveButton("Launch",(x,y)->{if(pet.snapshot().fuel<4){Toast.makeText(this,"Collect 4 biofuel first",0).show();return;}act(12,0);zoom=0;rebuild();}).setNegativeButton("Cancel",null).show();}}).show();}
 private void shop(boolean bag){PetState p=pet.snapshot();String[] labels=new String[PetState.ITEMS.length];for(int i=0;i<labels.length;i++){boolean own=(p.owned&(1<<i))!=0;labels[i]=PetState.ITEMS[i]+(own?"  •  Owned":bag?"  •  Locked":"  •  "+PetState.PRICES[i]+" coins");}new AlertDialog.Builder(this).setTitle(bag?"Inventory":"Shop  •  "+p.coins+" coins").setItems(labels,(d,i)->{PetState before=pet.snapshot();if(bag){if((before.owned&(1<<i))==0)Toast.makeText(this,"Buy this item first",0).show();else act(11,i);}else{if((before.owned&(1<<i))!=0)Toast.makeText(this,"Already owned",0).show();else if(before.coins<PetState.PRICES[i])Toast.makeText(this,"Not enough coins",0).show();else act(10,i);}shop(bag);}).setNegativeButton("Close",null).show();}
 private void act(int a,int v){pet.action(a,v);update();}
 private void rebuild(){actions.removeAllViews();LinearLayout r=new LinearLayout(this);actions.addView(r);PetState s=pet.snapshot();displayedStage=s.stage;if(playing){button(r,"Finish",()->finishGame());}
 else if(s.stage==0){button(r,"Hatch egg",()->{pet.action(0,0);rebuild();});button(r,"Land",()->act(6,0));button(r,"Water",()->act(6,1));button(r,"Sky",()->act(6,2));}
 else if(zoom==0){button(r,"Visit field",()->{zoom=1;rebuild();});}
 else if(zoom==1){button(r,"Clean field",()->act(3,0));button(r,"Land",()->act(6,0));button(r,"Water",()->act(6,1));button(r,"Sky",()->act(6,2));}
 else if(zoom==2){button(r,"Feed",()->new AlertDialog.Builder(this).setTitle("Choose food").setItems(new String[]{"Meat","Carrot","Fish","Grain"},(d,i)->act(1,i)).show());button(r,"Play",()->act(2,0));button(r,"Mini game",()->{hits=0;playing=true;gameEnd=SystemClock.elapsedRealtime()+15000;rebuild();});
 if(s.stage==PetState.ADULT){LinearLayout social=new LinearLayout(this);actions.addView(social);button(social,"Playdate",()->{act(8,0);rebuild();});button(social,"Breed",()->{PetState p=pet.snapshot();if(p.friendship<4){Toast.makeText(this,"Friendship must reach 4",0).show();return;}new AlertDialog.Builder(this).setTitle("Start a new generation?").setMessage("Your pet's next egg inherits the local partner's eye and color traits.").setNegativeButton("Cancel",null).setPositiveButton("Accept",(d,i)->{pet.action(9,0);rebuild();}).show();});}}
 else {button(r,"Inspect cells",()->{act(5,0);rebuild();});button(r,"Treat",()->{if(pet.snapshot().sick)act(4,0);else Toast.makeText(this,"No sick cells detected",0).show();});}update();}
 private void finishGame(){if(!playing)return;playing=false;pet.action(7,hits);rebuild();}
 private void update(){PetState s=pet.snapshot();if(!playing&&s.stage!=displayedStage){rebuild();return;}status.setText(s.creature()+"  •  Gen "+s.generation+"  •  "+s.fieldName()+"  •  "+s.coins+" coins\nFood "+s.hunger+"/5     Happy "+s.happy+"/10     Care "+s.mistakes);caption.setText(playing?"Time: "+Math.max(0,(gameEnd-SystemClock.elapsedRealtime()+999)/1000)+"s":s.stage==0?"Tap your egg to begin":zoom==3?(s.sick?"Tap to remove "+s.germs+" sick cells":s.stage==PetState.BABY?(s.nextCell()>0?"Next field cell in "+(s.nextCell()/60)+":"+(s.nextCell()%60<10?"0":"")+(s.nextCell()%60):"4 cells ready — tap to evolve"):"Diet and care record"):s.sick?"Your pet needs treatment in Cell":s.stage==PetState.ADULT?"Local playdate friendship: "+s.friendship+"/4":"Your pet lives even while the app is closed");scene.invalidate();}
 @Override protected void onStart(){super.onStart();active=true;h.post(refresh);}
 @Override protected void onStop(){active=false;h.removeCallbacks(refresh);if(playing)finishGame();pet.flush();super.onStop();}
}
